import { DndContext, DragOverlay } from "@dnd-kit/core";
import Board from "./components/Board";
import { useBoard } from "./hooks/useBoard";
import { arrayMove } from "@dnd-kit/sortable";
import { BoardState, Column } from "./types";
import { useState } from "react";
import CardItem from "./components/Card";

function App() {
  const { board, setBoard } = useBoard();
  const [activeId, setActiveId] = useState<string | null>(null);
  const findColumn = (board: BoardState, cardId: string) => {
    return Object.values(board.columns).find((col: Column) =>
      col.cardIds.includes(cardId),
    );
  };
  const handleDragStart = (event: any) => {
    setActiveId(event.active.id);
  };
  const handleDragEnd = (event: any) => {
    setActiveId(null);

    const { active, over } = event;

    if (!over) return;

    setBoard((prev) => {
      const sourceCol = findColumn(prev, active.id);

      if (!sourceCol) return prev;

      // 🔥 CASE: Dropping on column (empty space / bottom)
      if (over.id in prev.columns) {
        const destCol = prev.columns[over.id];
        console.log(destCol.cardIds.includes(active.id),active.id, destCol.cardIds)
        // if(destCol.cardIds.includes(active.id))
        //   return prev;
        const sourceItems = [...sourceCol.cardIds];
        const destItems = [...destCol.cardIds];

        // remove from source
        const sourceIndex = sourceItems.indexOf(active.id);
        sourceItems.splice(sourceIndex, 1);

        // add to END of destination
        destItems.push(active.id);

        console.log("1st log", {
          ...prev,
          columns: {
            ...prev.columns,
            [sourceCol.id]: {
              ...sourceCol,
              cardIds: sourceItems,
            },
            [destCol.id]: {
              ...destCol,
              cardIds: destItems,
            },
          },
        });
        return {
          ...prev,
          columns: {
            ...prev.columns,
            [sourceCol.id]: {
              ...sourceCol,
              cardIds: sourceItems,
            },
            [destCol.id]: {
              ...destCol,
              cardIds: destItems,
            },
          },
        };
      }

      // 🔵 CASE: Dropping on another card
      const destCol = findColumn(prev, over.id);

      if (!destCol) return prev;

      // same column
      if (sourceCol.id === destCol.id) {
        const oldIndex = sourceCol.cardIds.indexOf(active.id);
        const newIndex = destCol.cardIds.indexOf(over.id);
        console.log("2nd log", {
          ...prev,
          columns: {
            ...prev.columns,
            [sourceCol.id]: {
              ...sourceCol,
              cardIds: arrayMove(sourceCol.cardIds, oldIndex, newIndex),
            },
          },
        });
        return {
          ...prev,
          columns: {
            ...prev.columns,
            [sourceCol.id]: {
              ...sourceCol,
              cardIds: arrayMove(sourceCol.cardIds, oldIndex, newIndex),
            },
          },
        };
      }

      // cross column (drop on card)
      const sourceItems = [...sourceCol.cardIds];
      const destItems = [...destCol.cardIds];

      const sourceIndex = sourceItems.indexOf(active.id);
      sourceItems.splice(sourceIndex, 1);

      const destIndex = destItems.indexOf(over.id);
      destItems.splice(destIndex, 0, active.id);
      console.log("3rd log", {
        ...prev,
        columns: {
          ...prev.columns,
          [sourceCol.id]: {
            ...sourceCol,
            cardIds: sourceItems,
          },
          [destCol.id]: {
            ...destCol,
            cardIds: destItems,
          },
        },
      });
      return {
        ...prev,
        columns: {
          ...prev.columns,
          [sourceCol.id]: {
            ...sourceCol,
            cardIds: sourceItems,
          },
          [destCol.id]: {
            ...destCol,
            cardIds: destItems,
          },
        },
      };
    });
  };
  const handleDragOver = (event: any) => {
  const { active, over } = event;

  if (!over) return;

  setBoard((prev) => {
    const sourceCol = findColumn(prev, active.id);
    if (!sourceCol) return prev;

    let destCol: Column | undefined;

    // 🔥 Detect if hovering column OR card
    if (over.id in prev.columns) {
      destCol = prev.columns[over.id];
    } else {
      destCol = findColumn(prev, over.id);
    }

    if (!destCol) return prev;

    // 🧠 👉 ADD YOUR BLOCK HERE (replace old logic)
    const sourceItems = [...sourceCol.cardIds];
    const destItems = [...destCol.cardIds];

    const sourceIndex = sourceItems.indexOf(active.id);

    // remove from source
    if (sourceIndex !== -1) {
      sourceItems.splice(sourceIndex, 1);
    }

    // remove if already exists in destination
    const existingIndex = destItems.indexOf(active.id);
    if (existingIndex !== -1) {
      destItems.splice(existingIndex, 1);
    }

    let destIndex;

    // 👉 dropping on column (empty space)
    if (over.id in prev.columns) {
      destIndex = 0; // or destItems.length for bottom
    } else {
      destIndex = destItems.indexOf(over.id);
    }

    destItems.splice(destIndex, 0, active.id);

    return {
      ...prev,
      columns: {
        ...prev.columns,
        [sourceCol.id]: {
          ...sourceCol,
          cardIds: sourceItems,
        },
        [destCol.id]: {
          ...destCol,
          cardIds: destItems,
        },
      },
    };
  });
};
